mapper.select:
SELECT id, dataset_id, file_id, file_name, table_name, table_format, row_count, column_count, ordinal
FROM dataset_tables
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND dataset_id = #{datasetId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}

mapper.update:
UPDATE dataset_tables
SET table_name = #{tableName}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND dataset_id = #{datasetId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}

mapper.delete:
DELETE FROM dataset_tables
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND dataset_id = #{datasetId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}

mapper.select:
SELECT COUNT(*)
FROM dataset_tables
WHERE file_id = #{fileId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
